importScripts('/vendor/xlsx/xlsx.full.min.js');
self.onmessage=function(event){try{const book=XLSX.read(event.data,{type:'array',dense:true,cellDates:false,sheetRows:10001,bookVBA:false});if(book.SheetNames.length>40)throw new Error('الملف يتجاوز 40 ورقة.');const sheets=book.SheetNames.map(name=>{const rows=XLSX.utils.sheet_to_json(book.Sheets[name],{header:1,raw:false,defval:''});if(rows.length>10000)throw new Error('الحد الأعلى 10,000 صف في الورقة.');return {name,rows:rows.map(row=>row.slice(0,60).map(x=>String(x).slice(0,2000)))}});self.postMessage({sheets})}catch(e){self.postMessage({error:e.message||'تعذرت قراءة ملف Excel.'})}};
